import time
from functools import partial

from taf.rfrl.procedures.resources.python.logger import log_warning


def raise_when_output_is_empty(func):
    """
    Decorator which add to func additional assertion.

    :param func: Function
    :return: Output of function
    :raise ValueError: Raise when length of output func equals 0
    """
    def wrapper(*args, **kwargs):
        output = func(*args, **kwargs)
        if len(output) == 0:
            raise ValueError("Output is empty.\n Output: {}".format(output))
        return output
    return wrapper


def repeat_operation_when_exception_occurs(exception, rep_number=3, sleep_time=10):
    """
    Dynamic decorator which causes function repetition in case if particular exception occurs.
    Decorated function will be repeated a maximum of `rep_number` times in case of `exception`.
    Additional warning log and `sleep_time` sleep is performed before next function repetition.

    :param exception: name of exception to cause repetition
    :type exception: exception class
    :param rep_number: maximum number of repetitions of function re-try
    :type rep_number: int
    :param sleep_time: time (in seconds) to wait before each repetition
    :type sleep_time: int

    Example usage:

        @repeat_operation_when_exception_occurs(exception=WebDriverException, rep_number=2, sleep_time=5)
        def login(self, url, username, password, screenshot_dir=None, download_dir=None, browser='Firefox',
              sync_full_rack=False):
              ...
    """
    def decorator_engine(func, exception=exception, rep_number=rep_number, sleep_time=sleep_time):

        def wrapper(*args, **kwargs):
            for _ in range(rep_number):
                try:
                    return func(*args, **kwargs)
                except exception as exc:
                    log_warning(f"Operation '{func.__name__}' will be repeated due to {exc.__class__.__name__} "
                                f"exception: {str(exc)}")
                    time.sleep(sleep_time)
            return func(*args, **kwargs)

        return wrapper

    return partial(decorator_engine, exception=exception, rep_number=rep_number, sleep_time=sleep_time)
